# [HELPER] speech_models.py\n# Utilities for managing language models, punctuation, and normalization\n# helpers for IBM Watson Speech-to-Text streaming.\n\nimport os\n\n# ----------------------------------------------------------------------\n# Provider-specific language model constants (Watson STT)\n# ----------------------------------------------------------------------\n# These models are examples; users can override via environment variables.\nBASE_MODELS = {\n    'en': 'en-US_BroadbandModel',\n    'es': 'es-ES_BroadbandModel',\n    'fr': 'fr-FR_BroadbandModel',\n    'de': 'de-DE_BroadbandModel',\n    'pt': 'pt-PT_BroadbandModel',\n}  # mapping language code to Watson model name\n\n# ----------------------------------------------------------------------\n# Helper: select language model based on a 2‑letter ISO code\n# ----------------------------------------------------------------------\ndef get_language_model(lang_code: str = 'en') -> str:\n    \"\"\"Return the Watson model name for the requested language.\n\n    Args:\n        lang_code: ISO 639‑1 two‑letter code (default 'en').\n    \"\"\"\n    return os.getenv(\n        f'IBM_STT_MODEL_{lang_code.upper()}',\n        BASE_MODELS.get(lang_code.lower(), 'en-US_BroadbandModel')\n    )\n\n# ----------------------------------------------------------------------\n# Helper: decide whether to enable punctuation\n# ----------------------------------------------------------------------\ndef enable_punctuation(flag: bool = True) -> str:\n    \"\"\"Return a string recognized by Watson ('true' / 'false').\n\n    Args:\n        flag: Python bool indicating whether punctuation should be produced.\n    \"\"\"\n    return 'true' if flag else 'false'\n\n# ----------------------------------------------------------------------\n# Normalization helpers for transcripts (optional post‑processing)\n# ----------------------------------------------------------------------\nimport re\n\ndef normalize_text(text: str) -> str:\n    \"\"\"Simple normalization: trim, collapse whitespace, and lower‑case.\n\n    Args:\n        text: raw transcript string.\n    \"\"\"\n    text = text.strip()\n    text = re.sub(r'\\s+', ' ', text)\n    return text.lower()\n\n# ----------------------------------------------------------------------\n# Example usage (quick demo)\n# ----------------------------------------------------------------------\nif __name__ == '__main__':\n    print('Default English model:', get_language_model())\n    print('Spanish model:', get_language_model('es'))\n    print('Punctuation on?', enable_punctuation(True))\n    sample = \"  Hello,  world!    \"\n    print('Normalized:', normalize_text(sample))\n